import{_ as d,o as e,c as a,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Independent-Samples-Mode.md","filePath":"manual-zh/Independent-Samples-Mode.md","lastUpdated":1785684581000}'),n={name:"manual-zh/Independent-Samples-Mode.md"};function o(p,t,r,i,h,l){return e(),a("div",null,[...t[0]||(t[0]=[s('<h4 id="_15-13-2-独立样本模式" tabindex="-1">15.13.2 独立样本模式 <a class="header-anchor" href="#_15-13-2-独立样本模式" aria-label="Permalink to &quot;15.13.2 独立样本模式&quot;">​</a></h4><p><code>GROUPS</code> 子命令调用独立样本模式或“组”模式。此模式用于检验两组数值是否具有相同的总体均值。在此模式下，您还必须使用 <code>/VARIABLES</code> 子命令来告诉 PSPP 您要检验的因变量。</p><p><code>GROUPS</code> 子命令中给出的变量是决定样本所属组的自变量。括号中的值是每个组的自变量特定值。如果省略括号且未给出值，则假定默认值为 1.0 和 2.0。</p><p>如果自变量是数值型的，则可以在括号内只指定一个值。如果这样做，自变量大于或等于此值的个案属于第一组，小于此值的个案属于第二组。使用这种形式的 <code>GROUPS</code> 子命令时，无论是否指定了 <code>/MISSING=LISTWISE</code>，自变量中的缺失值都按列表方式排除。</p><h4 id="_15-13-2-1-示例-独立样本-t-检验" tabindex="-1">15.13.2.1 示例 - 独立样本 T 检验 <a class="header-anchor" href="#_15-13-2-1-示例-独立样本-t-检验" aria-label="Permalink to &quot;15.13.2.1 示例 - 独立样本 T 检验&quot;">​</a></h4><p>研究人员想知道在总体中，成年男性是否比成年女性高。样本从所研究的总体中抽取，并记录在文件 physiology.sav 中。</p><p>如前所述（见 <a href="./Identifying-incorrect-data">识别不正确的数据</a>），数据集中有一个样本包含明显不正确的身高值。因此使用 <code>SELECT</code> 命令将其排除在分析之外。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;physiology.sav&#39;.  select if (height &gt;= 200).  t-test /variables = height        /groups = sex(0,1).</span></span></code></pre></div><p><strong>示例 15.7：</strong> 在排除所有小于 200 公斤的观测值后运行独立样本 T 检验</p><p>原假设是男性和女性的平均身高相等。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>截图 15.6：</strong> 使用独立样本 T 检验对话框，检验 <strong>height</strong> 在 <strong>sex</strong> 各取值之间的差异</p><p>在这种情况下，分组变量是 <strong>sex</strong>，因此将其作为 <code>GROUP</code> 子命令的变量输入。组值为 0（男性）和 1（女性）。</p><p>如果您使用语法运行该过程，则需要将对应于每个组的值输入括号内。如果您使用图形用户界面，则必须打开“定义组”对话框，并如截图 15.7 所示输入对应于每个组的值。如果像本例这样，数据集已为分组变量定义了值标签，则可以通过标签或值输入它们。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>截图 15.7：</strong> 为独立样本 T 检验设置分组变量的值</p><p>从结果 15.5 可以清楚地看到，男性的 <em>样本</em> 平均身高大于女性。然而，要判断这是否是显著结果，必须参考 T 检验表。</p><p>T 检验表包含两行；一行用于可安全假设各组样本方差相等的情况，第二行用于不能安全假设各组方差相等的情况。</p><p>然而在本例中，两行都显示双尾显著性小于 0.001，因此必须拒绝原假设，并得出总体中男性和女性的平均身高不相等的结论。</p><table tabindex="0"><thead><tr><th></th><th></th><th>F</th><th>Sig.</th><th>t</th><th>df</th><th>Sig.（双尾）</th><th>均值差</th><th>标准误差</th><th>差值的 95% 置信区间</th><th></th></tr></thead><tbody><tr><td></td><td>组</td><td>N</td><td>均值</td><td>标准差</td><td>S.E. 均值</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>身高（毫米）</td><td>男性</td><td>22</td><td>1796.49</td><td>49.71</td><td>10.60</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>女性</td><td>17</td><td>1610.77</td><td>25.43</td><td>6.17</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>方差齐性 Levene 检验</td><td>均值相等性的 T 检验</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>下限</td><td>上限</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>身高（毫米）</td><td>假设方差相等</td><td>.97</td><td>.331</td><td>14.02</td><td>37.00</td><td>.000</td><td>185.72</td><td>13.24</td><td>158.88</td><td>212.55</td></tr><tr><td>不假设方差相等</td><td></td><td></td><td>15.15</td><td>32.71</td><td>.000</td><td>185.72</td><td>12.26</td><td>160.76</td><td>210.67</td><td></td></tr></tbody></table><p><strong>结果 15.5：</strong> 按 <strong>sex</strong> 对 <strong>height</strong> 进行独立样本 T 检验的结果</p>',21)])])}const u=d(n,[["render",o]]);export{g as __pageData,u as default};
